  "自动化任务：定时、系统通知或 HTTP 信号触发后，用 DSL 构造提示词并新建一个 Chat 会话发送。": "Automatisierte Aufgaben: Nachdem die Zeitmessung, die Systembenachrichtigung oder das HTTP-Signal ausgelöst wurde, verwenden Sie DSL, um Aufforderungswörter zu erstellen und eine neue Chat-Sitzung zum Senden zu erstellen.",
