  "Code 模式覆盖": "Überschreiben des Codemodus",
  "拦截时确认升级": "Bestätigen Sie das Upgrade beim Abfangen",
  "命令被沙箱拦截或后端不可用时，弹窗确认后以完全权限重试（关闭则直接报错）": "Wenn der Befehl von der Sandbox abgefangen wird oder das Backend nicht verfügbar ist, wird ein Popup-Fenster zur Bestätigung und zum erneuten Versuch mit vollständigen Berechtigungen angezeigt (wenn geschlossen, wird ein Fehler direkt gemeldet).",
  "后端状态": "Backend-Status",
  "运行自检": "Führen Sie einen Selbsttest durch",
  "运行位置": "Betriebsposition",
  "本机（当前系统）": "Diese Maschine (aktuelles System)",
  "命令与终端运行在": "Befehl und Terminal laufen ein",
  "虚拟机（CIBYP-VM-OS）": "Virtuelle Maschine (CIBYP-VM-OS)",
  "工作区模式": "Arbeitsbereichsmodus",
  "选择虚拟机后：终端、Shell / Python / Node、文件读写、文档与媒体工具、浏览器自动化全部作用于隔离的 Linux 环境；切换需要重启应用。": "Nach Auswahl der virtuellen Maschine funktionieren Terminal, Shell/Python/Node, Lesen und Schreiben von Dateien, Dokument- und Medientools sowie Browserautomatisierung alle in der isolierten Linux-Umgebung. Für den Wechsel ist ein Neustart der Anwendung erforderlich.",
  "共享工作区（本机为准 + 双向同步）": "Gemeinsamer Arbeitsbereich (lokaler Computer + bidirektionale Synchronisierung)",
  "独立工作区（虚拟机内为准）": "Unabhängiger Arbeitsbereich (vorbehaltlich innerhalb der virtuellen Maschine)",
  "共享：文件留在本机，虚拟机通过": "Freigabe: Die Dateien bleiben auf der lokalen Maschine und die virtuelle Maschine wird weitergeleitet",
  "双向增量同步；": "Zwei-Wege-Inkrementalsynchronisation;",
  "重置虚拟机不会丢工作区": "Durch das Zurücksetzen einer virtuellen Maschine geht der Arbeitsbereich nicht verloren",
  "未同步": "Nicht synchronisiert",
  "。独立：工作区只在虚拟机内，需要时显式导出（隔离更强）。": ". Unabhängig: Der Arbeitsbereich befindet sich nur innerhalb der virtuellen Maschine und wird bei Bedarf explizit exportiert (stärkere Isolation).",
  "立即同步": "Jetzt synchronisieren",
  "工作区同步": "Synchronisierung des Arbeitsbereichs",
  "仅推送": "Nur drücken",
  "更换目录": "Verzeichnis wechseln",
  "仅拉回": "Nur zurückziehen",
  "状态": "Zustand",
  "虚拟机沙盒（CIBYP-VM-OS）": "Sandbox für virtuelle Maschinen (CIBYP-VM-OS)",
  "立即重启应用": "Starten Sie die App jetzt neu",
  "打开 VM 桌面": "Öffnen Sie den VM-Desktop",
  "资源": "Ressource",
  "虚拟机文件管理器": "Dateimanager für virtuelle Maschinen",
  "下载 / 更新": "Herunterladen/Aktualisieren",
  "镜像变体": "Spiegelvariante",
  "自检": "Selbsttest",
  "打开目录": "Verzeichnis öffnen",
  "重置虚拟机": "Virtuelle Maschine zurücksetzen",
  "未检测": "Nicht erkannt",
  "端口预览": "Hafenvorschau",
  "开启 WHPX 硬件加速": "Aktivieren Sie die WHPX-Hardwarebeschleunigung",
  "检查 QEMU 运行时、硬件加速（Windows: WHPX / Linux: KVM / macOS: HVF）与镜像完整性；无硬件加速时退化为软件模拟（较慢，需管理员权限开启 WHPX）。": "Überprüfen Sie die QEMU-Laufzeit, die Hardwarebeschleunigung (Windows: WHPX / Linux: KVM / macOS: HVF) und die Bildintegrität. Ohne Hardwarebeschleunigung degradiert es zur Softwaresimulation (langsamer, Administratorrechte sind erforderlich, um WHPX zu aktivieren).",
  "VM 内端口，如 3000": "Interner VM-Port, z. B. 3000",
  "未映射端口": "Nicht zugeordneter Port",
  "映射到本机": "Zu lokal zuordnen",
  "在虚拟机内下载文件": "Laden Sie Dateien innerhalb der virtuellen Maschine herunter",
  "在虚拟机里起的开发服务器可通过这里映射到宿主 127.0.0.1，用内置浏览器预览。": "Der in der virtuellen Maschine gestartete Entwicklungsserver kann hier dem Host 127.0.0.1 zugeordnet und über den integrierten Browser in der Vorschau angezeigt werden.",
  "下载": "herunterladen",
  "虚拟机内目录": "Verzeichnis innerhalb der virtuellen Maschine",
  "宿主 aria2 多连接下载后自动送入虚拟机；GitHub 链接可用加速镜像": "Die Host-Aria2-Mehrfachverbindung wird nach dem Herunterladen automatisch an die virtuelle Maschine gesendet. Zur Beschleunigung des Images kann der GitHub-Link genutzt werden",
  "隐私信息保护": "Schutz der Privatsphäre",
  "启用隐私信息保护": "Aktivieren Sie den Datenschutz",
  "启用后，在工具调用过程中自动过滤手机号、证件号、社保号、API Key、SSH 私钥、.env 密钥行、Tor Hidden Service 地址、git key 以及配置文件（json/yaml/config 等）中的密码，防止隐私信息进入 AI 上下文与历史记录。": "Nach der Aktivierung werden die Mobiltelefonnummer, die ID-Nummer, die Sozialversicherungsnummer, der API-Schlüssel, der private SSH-Schlüssel, die .env-Schlüsselzeile, die Tor Hidden Service-Adresse, der Git-Schlüssel und die Passwörter in Konfigurationsdateien (json/yaml/config usw.) während des Tool-Aufrufprozesses automatisch gefiltert, um zu verhindern, dass private Informationen in den KI-Kontext und -Verlauf gelangen.",
  "工具结果过滤": "Tool-Ergebnisfilterung",
  "过滤触发器（需开启总开关后生效）": "Filterauslöser (muss den Hauptschalter einschalten, um wirksam zu werden)",
  "工具返回内容注入 AI 上下文前过滤": "Das Tool gibt gefilterte Inhalte zurück, bevor sie in den KI-Kontext eingefügt werden",
  "写入上下文时隐藏参数中的密码、Token、密钥": "Blenden Sie Passwörter, Token und Schlüssel in Parametern aus, wenn Sie Kontext schreiben",
  "工具参数脱敏": "Desensibilisierung der Werkzeugparameter",
  "终端内容过滤": "Filterung von Terminalinhalten",
  "终端命令与脚本中的密钥、Token 脱敏": "Desensibilisierung von Schlüsseln und Token in Terminalbefehlen und Skripten",
  "附件文本过滤": "Filterung von Anhangstexten",
  "手机号": "Telefonnummer",
  "上传附件的 OCR/提取文本过滤": "OCR-/Textextraktionsfilterung hochgeladener Anhänge",
  "过滤内容类别（可单独关闭）": "Inhaltskategorien filtern (kann einzeln ausgeschaltet werden)",
  "身份证号": "ID-Nummer",
  "SSH 私钥": "Privater SSH-Schlüssel",
