  "启用托盘图标": "Taskleistensymbol aktivieren",
  "关闭后应用将不在系统托盘显示图标，关闭窗口即退出。": "Nach dem Schließen zeigt die Anwendung das Symbol nicht mehr in der Taskleiste an und wird beendet, wenn das Fenster geschlossen wird.",
  "测试：隐藏到托盘": "Test: Im Fach verstecken",
  "关闭窗口时": "Beim Schließen des Fensters",
  "每次询问": "Jedes Mal fragen",
  "始终后台运行": "Immer im Hintergrund laufen",
  "始终直接退出": "Immer sofort beenden",
  "点击后窗口将立即最小化到托盘，可单击托盘图标恢复。": "Das Fenster wird sofort in den Infobereich minimiert. Ein Klick auf das Symbol stellt es wieder her.",
  "\"每次询问\"将在关闭窗口时弹窗询问您的偏好。\"始终\"选项会记住选择。": "„Jedes Mal fragen“ zeigt beim Schließen eine Auswahl. „Immer“ speichert die Auswahl.",
  "网络搜索": "Websuche",
  "默认搜索引擎": "Standardsuchmaschine",
  "Fusion 同时查询四个引擎、去重并按相关度排序。默认使用免登录 MCP；也可配置自己的 Provider、地址和 Key。免登录服务的可用性和限额由服务方决定。": "Fusion fragt vier Suchmaschinen ab, entfernt Duplikate und sortiert nach Relevanz. Standardmäßig wird MCP ohne Anmeldung verwendet. Eigene Anbieter, Endpunkte und Schlüssel sind ebenfalls möglich. Verfügbarkeit und Limits legt der Anbieter fest.",
  "地址（留空使用默认）": "Adresse (leer für Standard)",
  "MCP 工具名（可选）": "MCP-Toolname (optional)",
  "服务配置": "Dienstkonfiguration",
  "1. 访问": "1. Besuchen",
  "2. 添加：": "2. Hinzufügen:",
  "代理即时生效（无需重启），覆盖：AI/VLM/生图请求、模型列表、网页抓取与 net:* 工具、Playwright 浏览器、aria2 下载、npm/curl 等子进程。DNS/ping/traceroute 等底层探测与 IMAP 收信始终直连。": "Proxy-Änderungen gelten sofort für KI/VLM/Bilder, Modelllisten, Webabrufe, net:*-Tools, Playwright, aria2 und Unterprozesse wie npm/curl. DNS/ping/traceroute und IMAP verwenden weiterhin direkte Verbindungen.",
  "1. 在 Arduino IDE 中打开导出的": "1. In der Arduino IDE die exportierte Datei öffnen",
  "2. Tools → Board → esp32 → 选择你的 ESP32 型号（如 ESP32 Dev Module）": "2. Tools → Board → esp32 → ESP32-Modell auswählen (z. B. ESP32 Dev Module)",
  "3. Tools → Board → Boards Manager → 搜索 \"ESP32\"": "3. Tools → Board → Boards Manager → nach „ESP32“ suchen",
  "3. Tools → Port → 选择对应的 COM 端口": "3. Tools → Port → passenden COM-Port auswählen",
  "下载设置": "Download-Einstellungen",
  "4. （可选）在代码中修改 WiFi SSID 和密码": "4. Optional WiFi-SSID und Passwort im Code ändern",
  "5. 点击 Arduino IDE 顶部的 \"Upload\" 按钮（右箭头图标）": "5. Oben in der Arduino IDE auf „Upload“ klicken (Pfeil nach rechts)",
  "语音模型体积较大，不再随安装包分发。模型由你手动下载，下载后即时生效、无需重启；下载引擎优先使用内置 aria2（多连接加速），不可用时自动回退普通下载。": "Die großen Sprachmodelle sind nicht im Installationspaket enthalten. Laden Sie sie manuell herunter; sie sind ohne Neustart nutzbar. aria2 beschleunigt den Download mit mehreren Verbindungen. Bei Bedarf wird ein normaler Download verwendet.",
  "官方源（huggingface.co）": "Offizielle Quelle (huggingface.co)",
  "CN 镜像（hf-mirror.com，推荐国内网络）": "China-Spiegel (hf-mirror.com, für chinesische Netze empfohlen)",
  "下载源": "Download-Quelle",
  "模型下载目录": "Modell-Downloadordner",
  "选择目录": "Ordner auswählen",
  "默认：程序数据目录/voice-models": "Standard: Programm-Datenordner/voice-models",
  "唤醒词 KWS 托管在 GitHub Release，不受镜像选择影响": "Das KWS-Aktivierungswortmodell liegt auf GitHub Releases und verwendet keinen Spiegel",
  "下载全部必需模型": "Alle erforderlichen Modelle herunterladen",
  "默认程序数据目录；自定义目录对所有语音模型生效": "Standardmäßig Programm-Datenordner; eigene Ordner gelten für alle Sprachmodelle",
  "必需模型合计约 440MB（VAD + KWS + Whisper base + Kokoro）": "Erforderliche Modelle: insgesamt ca. 440 MB (VAD + KWS + Whisper base + Kokoro)",
  "语音模型": "Sprachmodelle",
  "使用说明": "Anleitung",
  "正在读取模型状态…": "Modellstatus wird gelesen…",
  "下载中断可再次点击「下载」，已完成的文件会自动跳过；aria2 支持断点续传。": "Nach einer Unterbrechung erneut „Herunterladen“ wählen. Fertige Dateien werden übersprungen; aria2 unterstützt das Fortsetzen.",
  "未下载模型时，「语音」设置页不可用，启动时会自动关闭已开启的语音开关，避免运行时报错。": "Ohne Modelle sind Spracheinstellungen deaktiviert. Beim Start werden Sprachfunktionen ausgeschaltet, deren Modelle fehlen.",
  "模型来源：sherpa-onnx 官方发布（HuggingFace csukuangfj/* / GitHub k2-fsa）。": "Modellquelle: offizielle sherpa-onnx-Veröffentlichungen (HuggingFace csukuangfj/* / GitHub k2-fsa).",
  "开发环境检测": "Entwicklungsumgebung prüfen",
  "删除模型只影响当前下载目录中的文件；如果你使用自定义目录，请确保磁盘空间充足。": "Das Löschen betrifft nur den aktuellen Downloadordner. Bei einem eigenen Ordner ausreichend freien Speicher sicherstellen.",
  "重新检测": "Erneut prüfen",
  "检测结果": "Prüfergebnisse",
  "点击“重新检测”开始检测": "Zum Starten auf „Erneut prüfen“ klicken",
  "自动更新检查": "Automatische Updateprüfung",
  "检测本机是否已安装 Python、Git，以及 JavaScript 运行时（Node+npm 与 Bun 任选其一）及其版本。检测不到的组件，可以让 Agent 打开一个新 Chat 会话帮你安装。": "Prüft Python, Git und die JavaScript-Laufzeit (Node+npm oder Bun) samt Version. Fehlende Komponenten kann der Agent in einem neuen Chat installieren.",
  "检查间隔": "Prüfintervall",
  "自动检查更新": "Automatisch nach Updates suchen",
  "每 12 小时": "Alle 12 Stunden",
  "每 6 小时": "Alle 6 Stunden",
  "启动后延迟检查一次，之后按下方间隔定时检查 GitHub Releases。发现新版本时通过系统通知提醒（可在「通知」中关闭）。检查失败不会打扰你。": "Prüft nach dem Start verzögert und anschließend im gewählten Intervall die GitHub Releases. Neue Versionen werden als Systembenachrichtigung angezeigt; deaktivierbar unter „Benachrichtigungen“. Fehlgeschlagene Prüfungen bleiben still.",
  "每 24 小时": "Alle 24 Stunden",
