  "仅稳定版只获取正式发布版本；全部版本同时包含 alpha/beta 等预发布版本。默认仅稳定版。": "„Nur stabile Versionen“ berücksichtigt ausschließlich fertige Releases. „Alle Versionen“ umfasst auch Alpha/Beta. Standard: nur stabile Versionen.",
