  "正在分批渲染消息，避免界面卡顿。大历史记录可能需要数秒。": "Nachrichten werden in Abschnitten gerendert, damit die Oberfläche flüssig bleibt. Große Verläufe können einige Sekunden dauern.",
  "例如 Partner": "Z. B. Partner",
  "OpenCode 官方将限时免费模型的容量保留给官方客户端（网关按": "OpenCode reserviert die Kapazität zeitweise kostenloser Modelle für offizielle Clients (das Gateway prüft",
